function site_build_example($eid) {
 $s=site_example_base();$old=site_read($eid);$defaults=site_default($eid);
 $s['name']=$defaults['name'];$s['slug']=$old['slug'];$s['seo_title']=$s['name'].' | Página de demonstração';
 foreach(['logo','hero_image'] as $key)$s[$key]=$old[$key]??'';
 $s['specialties']=array_values(array_filter($s['specialties'],static function($c)use($eid){return clinic_specialty_enabled($c['theme'],$eid);}));
 $descriptions=[];foreach(site_example_base()['specialties'] as $c)$descriptions[$c['theme']]=$c['text'];
 $oldPhotos=[];foreach($old['professionals']??[] as $c)if(!empty($c['user_id']))$oldPhotos[(int)$c['user_id']]=$c['image']??'';
 foreach(site_registered_professionals($eid) as $p){$theme=normalize_theme_choice($p['tema_preferido']);
  $s['professionals'][]=['user_id'=>(int)$p['id'],'name'=>$p['nome'],'role'=>$p['especialidade']?:$p['theme_label'],'registration'=>$p['registro_profissional']??'','text'=>'Apresentação de exemplo: '.($descriptions[$theme]??'Acompanhamento individualizado na sua área de atuação.').' Personalize este texto com as informações reais do profissional.','image'=>$oldPhotos[(int)$p['id']]??'','enabled'=>true];
 }
 if(count($s['professionals'])>24)throw new RuntimeException('O exemplo encontrou mais de 24 profissionais. Ajuste o limite de cartões antes de carregar a equipe completa.');
 return $s;
}
function site_apply_example($eid,$revision) {
 // site_save retains its concurrency lock. Back up before replacement, under that same lock.
 $lock=db()->query("SELECT GET_LOCK('clinicapp_website_config',5)");if((int)$lock->fetchColumn()!==1)throw new RuntimeException('Outro administrador está salvando. Tente novamente.');
 try{
  if(!hash_equals(site_revision($eid),(string)$revision))throw new RuntimeException('A página foi alterada em outra aba. Recarregue antes de carregar o exemplo.');
  $example=site_build_example($eid);$config=db()->prepare("SELECT chave,valor FROM configuracoes WHERE empresa_id=? AND chave IN ('website_config','website_slug')");$config->execute([(int)$eid]);$previous=$config->fetchAll(PDO::FETCH_KEY_PAIR);
  $q=db()->prepare("SELECT empresa_id FROM configuracoes WHERE chave='website_slug' AND valor=? AND empresa_id<>? LIMIT 1");$q->execute([$example['slug'],$eid]);if($q->fetchColumn())throw new RuntimeException('O endereço desta clínica já está em uso. Corrija o endereço antes de carregar o exemplo.');
  db()->beginTransaction();
  $q=db()->prepare("INSERT INTO configuracoes(empresa_id,chave,valor) VALUES(?,'website_example_backup',?) ON DUPLICATE KEY UPDATE valor=valor");$q->execute([(int)$eid,json_encode(['config_present'=>isset($previous['website_config']),'config'=>$previous['website_config']??null,'slug_present'=>isset($previous['website_slug']),'slug'=>$previous['website_slug']??null],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)]);
  if(!app_config_set('website_config',json_encode($example,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR),$eid)||!app_config_set('website_slug',$example['slug'],$eid))throw new RuntimeException('Não foi possível carregar o exemplo.');
  log_action('pagina_web_exemplo','empresas',$eid,'Exemplo carregado como rascunho; versão anterior preservada.');db()->commit();
 }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}finally{db()->query("SELECT RELEASE_LOCK('clinicapp_website_config')");}
}
